import type { Athlete, ArchetypeId, SportId, Ulti, UltiEffect } from '../engine/types';
import generated from './athletes.generated.json';

// Base de sportifs réels.
// - fame (0-100) : célébrité, estimée d'après l'audience (Wikipédia, réseaux). Elle fixe la rareté.
// - level (0-100) : note sportive affichée sur la carte. Pour les retraités, c'est leur niveau au sommet.
// Les faits restent volontairement sobres et vérifiables.

type Extra = Partial<Omit<Athlete, 'id' | 'first' | 'last' | 'sport' | 'archetype' | 'role' | 'country' | 'fame' | 'level' | 'fact'>>;

function a(
  id: string,
  first: string,
  last: string,
  sport: SportId,
  archetype: ArchetypeId,
  role: string,
  country: string,
  fame: number,
  level: number,
  fact: string,
  extra: Extra = {},
): Athlete {
  return { id, first, last, sport, archetype, role, country, fame, level, fact, ...extra };
}

function sig(id: string, name: string, desc: string, effect: UltiEffect | UltiEffect[]): Ulti {
  return { id: `sig-${id}`, name, desc, effects: Array.isArray(effect) ? effect : [effect], signature: true };
}

